package com.opensocket.aievent.core.issuetracking.application.relay;
import static org.junit.jupiter.api.Assertions.*; import java.util.*; import org.junit.jupiter.api.Test; import com.opensocket.aievent.core.issuetracking.relay.*;
class Phase3HIndependentEdgeAndCompensationTest { @Test void unavailableProviderFailsClosedWithoutDeletingCanonicalRelation(){var repo=new InMemoryRelayGovernanceRepository();var ledger=new RelayEventLedger(repo);var relationService=new CanonicalRelationService(repo,ledger);var topologyService=new RelayTopologyService(repo,ledger,new UnavailableA2ARelayPolicySignalPort());var edgeService=new RelayEdgeExecutionService(repo,new UnavailableRelayProviderGateway(),ledger,topologyService);var relation=relationService.create("t","PARENT_CHILD","p","c","s","d","actor","");var topology=topologyService.create("t",relation.relationId(),RelayTopologyType.ONE_TO_ONE,List.of(new RelayEdgeDefinition("conn","map","JIRA","ERP","ERP-1","MES-2",RelayEdgeType.PROVIDER_NATIVE_RELATION,"RELATES_TO")),"actor","");var edge=repo.listEdges("t",topology.topologyId(),null,10).getFirst();var failed=edgeService.execute("t",edge.edgeId(),edge.version(),"actor","test","");assertEquals(RelayEdgeStatus.FAILED_PERMANENT,failed.status());assertTrue(repo.findRelation("t",relation.relationId()).isPresent());assertEquals(RelayTopologyStatus.BROKEN,repo.findTopology("t",topology.topologyId()).orElseThrow().status());}}
